mapper.select:
select count(*)
from accounts
where username = #{username}

select count(*)
from users
where lower(coalesce(handle, id)) = #{handle}

mapper.update:
update accounts
set failed_login_attempts = 0,
    locked_until = null,
    last_login_at = #{now},
    updated_at = #{now}
where id = #{accountId}

update accounts
set failed_login_attempts = #{failedLoginAttempts},
    locked_until = #{lockedUntil},
    updated_at = #{updatedAt}
where id = #{accountId}

update auth_refresh_tokens
set revoked_at = #{revokedAt}, replaced_by_token_id = #{replacementId}
where id = #{id} and revoked_at is null

update auth_refresh_tokens rt
set revoked_at = current_timestamp
where rt.token_hash = #{tokenHash}
  and rt.revoked_at is null
  and exists (
      select 1
      from accounts a
      where a.id = rt.account_id and a.user_id = #{userId}
  )
